220	\begin{lemma}[Consistency and self-consistency of the pulled-apart measurements]\label{lem:qld-construct-the-paulis}
221		\lean{MIPStarRE.QPBT.exists_pulled_apart_consistency}
222		\lean{MIPStarRE.QPBT.deltaConstructPaulis}
223		\uses{def:tilde-m-measurement, def:tilde-w-observables,
224			lem:projective-strategy-setup, def:expanded-state, def:consistency,
225			def:approx-question-indexed-operators, lem:qld-4-7,
226			def:indicator-vector}
227		There are universal constants $a>1$, $0<b<1$, and $C_*\geq1$ such that,
228		for every admissible parameter tuple and projective strategy in the setting
229		above with $0\leq\eps\leq1$, there is a pair of global projective measurements
230		satisfying Lemma~\ref{lem:qld-4-7} at error $\delta_G(\eps,m,d,q)$.
231		The measurements $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ and observables
232		$\tilde{W}^j(\tilde{u})$ constructed from this same pair satisfy the following
233		properties, with all three constants taken to be $C_*$.
234		% The paper's statement also quantifies item 1 over j, but j does not occur
235		% in item 1; the vacuous quantifier is dropped here.
236		\begin{enumerate}
237			\item (\textbf{Consistency with points measurements}) For all $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
238			\[
239				\Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \simeq_{\delta_P^{\mathrm{AB}}} M^{(\mathrm{Point},W),u}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''}
240			\]
241			and
242			\[
243				\tilde{M}^{W,\mathrm{ind}_m(u)}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \simeq_{\delta_P^{\mathrm{BA}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot M^{(\mathrm{Point},W),u}_a\;,
244			\]
245			with the answer summation over $a \in \F_q$.
246			\item (\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and $j \in \{0,\ldots,t-1\}$, on average over uniformly random $\tilde{u} \in \F_q^{M}$,
247			\[
248				\tilde{W}^j(\tilde{u}) \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \approx_{\delta_P^{\mathrm{obs}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{W}^j(\tilde{u})\;.
249			\]
250		\end{enumerate}
251		The construction above does not assume a supplied global measurement. Its
252		remaining step is to extend Lemma~\ref{lem:qld-4-7} to zero error and combine
253		that measurement with the three conditional estimates below. This obligation
254		is recorded in \cite{gap:qpbt_extraction-transfer}.
255	\end{lemma}
256	\begin{proof}
257		\uses{lem:qld-4-7, lem:qld-constructing-the-paulis-helper, def:expanded-point-measurement, def:tilde-m-measurement, def:tau-dot-product-projector, lem:qld-decoder-evaluation, lem:qld-decoder-linearity, def:indicator-vector, lem:qld-win-implications, lem:qld-comm-cons, fact:add-a-proj, fact:agreement, fact:triangle, fact:data-processing, def:bracket, lem:povm-to-obs, lem:schwartz-zippel-total-degree}
258		% Support restriction added: the source (line 1492 of
140		The fibers of $h\mapsto h\cdot\tilde{u}$ partition $\F_q^M$, so
141		$\sum_a\tau^W_a(\tilde{u})=\sum_h\tau^W_h=\Id$.
142	\end{proof}
