144	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
145		\lean{MIPStarRE.QPBT.tildeM}
146		\leanok
147		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:qld-full-field-decoder}
148		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
149		\begin{equation}\label{eq:tilde_M}
150			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
151		\end{equation}
152		the sum ranging over $g \in \mathrm{ideg}_{d,m}(\F_q)$. If $\hat{S}^W_g$ is viewed as an operator acting on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), then $\tilde{M}^{W,\tilde{u}}_a$ acts on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ (resp.\ $\mathrm{B}\mathrm{B}'\mathrm{B}''$), the $\tau^W$ factor acting on $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
153	\end{definition}
154	
155	\begin{lemma}[Projectivity and completeness of the pulled-apart measurements]\label{lem:tilde-m-projective}
156		\lean{MIPStarRE.QPBT.tildeM_isProj, MIPStarRE.QPBT.sum_tildeM_eq_one}
157		\leanok
158		\uses{def:tilde-m-measurement, lem:s-w-marginals-projective,
159			lem:tau-dot-product-projective}
160		For each $W$ and $\tilde{u}$, every $\tilde{M}^{W,\tilde{u}}_a$ is a projector and
161		$\sum_{a\in\F_q}\tilde{M}^{W,\tilde{u}}_a=\Id$. Thus
162		$\{\tilde{M}^{W,\tilde{u}}_a\}_{a\in\F_q}$ is a projective measurement.
163	\end{lemma}
